<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#101820"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="apple-mobile-web-app-title" content="RunnerLog"><title>@yield('title','RunnerLog')</title><link rel="manifest" href="/manifest.webmanifest"><link rel="icon" href="/icons/icon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/icons/icon-192.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/css/runnerlog.css"></head>
<body class="@yield('bodyClass')">@yield('content')<div id="pwa-install-bar" hidden><button id="pwa-install-btn" type="button">INSTALL RUNNERLOG</button><button id="pwa-install-close" type="button" aria-label="Close">×</button></div><script>
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(console.error));}
let installPrompt=null;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;const bar=document.getElementById('pwa-install-bar');if(!localStorage.getItem('runnerlog-install-dismissed'))bar.hidden=false});
document.getElementById('pwa-install-btn').onclick=async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;document.getElementById('pwa-install-bar').hidden=true};
document.getElementById('pwa-install-close').onclick=()=>{document.getElementById('pwa-install-bar').hidden=true;localStorage.setItem('runnerlog-install-dismissed','1')};
</script></body></html>
